<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { accionPedido, detallePedido, guardarPedido, imprimirPedido, listarPedidos, opcionesPedido, type Pedido, type PedidoOptions } from '../services/pedidos'
const items=ref<Pedido[]>([]),options=ref<PedidoOptions>({estados:[],items:[],inversiones:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Pedido|null>(null),file=ref<File|null>(null),editing=ref<number|null>(null)
const filters=reactive({criterio:'',fecha_desde:'',fecha_hasta:'',tipo:'',estado:'',page:1}),form=reactive({tipo:'m' as 'm'|'s'|'a',prioridad:'normal',inversion_id:0,informacion:'',es_requerimiento_almacen:false,enviar_copia:false,detalles:[{item_id:0,cantidad:1,glosa:''}]})
const availableItems=computed(()=>options.value.items.filter(item=>item.tipo===form.tipo))
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=await listarPedidos(filters);items.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(cause){error.value=message(cause)}finally{loading.value=false}}
async function init(){try{options.value=await opcionesPedido()}catch{}await load()}
function open(item?:Pedido){editing.value=item?.id||null;Object.assign(form,{tipo:item?.tipo||'m',prioridad:item?.prioridad||'normal',inversion_id:0,informacion:item?.informacion||'',es_requerimiento_almacen:item?.es_requerimiento_almacen||false,enviar_copia:false,detalles:item?.detalles?.map(x=>({item_id:x.item_id,cantidad:x.cantidad,glosa:x.glosa||''}))||[{item_id:0,cantidad:1,glosa:''}]});file.value=null;modal.value=true}
function addLine(){form.detalles.push({item_id:0,cantidad:1,glosa:''})}function removeLine(i:number){if(form.detalles.length>1)form.detalles.splice(i,1)}function pick(e:Event){file.value=(e.target as HTMLInputElement).files?.[0]||null}
async function save(){if(!form.informacion.trim()||form.detalles.some(x=>!x.item_id||x.cantidad<1)){error.value='Complete la glosa y todos los ítems.';return}if(!form.es_requerimiento_almacen&&!editing.value&&!file.value){error.value='Adjunte el PDF de sustento.';return}const fd=new FormData();fd.append('tipo',form.tipo);fd.append('prioridad',form.prioridad);fd.append('inversion_id',String(form.inversion_id));fd.append('informacion',form.informacion);fd.append('es_requerimiento_almacen',form.es_requerimiento_almacen?'1':'0');fd.append('enviar_copia',form.enviar_copia?'1':'0');form.detalles.forEach((x,i)=>Object.entries(x).forEach(([k,v])=>fd.append(`items[${i}][${k==='item_id'?'codigo':k}]`,String(v))));if(file.value)fd.append('archivo',file.value);saving.value=true;try{await guardarPedido(editing.value,fd);success.value='Pedido guardado correctamente.';modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function action(item:Pedido,value:'enviar'|'anular'){if(!confirm(`¿${value} el pedido #${item.id}?`))return;try{await accionPedido(item.id,value);success.value=`Pedido ${value==='enviar'?'enviado':'anulado'} correctamente.`;await load()}catch(cause){error.value=message(cause)}}
async function show(item:Pedido){try{detail.value=await detallePedido(item.id)}catch(cause){error.value=message(cause)}}
function canEdit(item:Pedido){return ['0','5','abierto','borrador'].includes(String(item.estado).toLowerCase())}function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}onMounted(init)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Pedidos</nav><header class="hero"><div class="mark">MI</div><div><small>MIA · Logística</small><h1>Pedidos</h1><p>Registra y da seguimiento a requerimientos de materiales, activos y servicios.</p></div><strong>{{total}} pedidos</strong><button @click="open()">+ Nuevo pedido</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="filters"><label>Glosa o código<input v-model.trim="filters.criterio" @keyup.enter="load(1)"></label><label>Desde<input v-model="filters.fecha_desde" type="date"></label><label>Hasta<input v-model="filters.fecha_hasta" type="date"></label><label>Tipo<select v-model="filters.tipo"><option value="">Todos</option><option value="m">Material</option><option value="a">Activo</option><option value="s">Servicio</option></select></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="state in options.estados" :key="state.value" :value="state.value">{{state.label}}</option></select></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Cargando pedidos…</div><div v-else-if="!items.length" class="empty">No se encontraron pedidos.</div><section v-else class="table"><header><span>Código / tipo</span><span>Glosa</span><span>Fecha</span><span>Estado</span><span>Acciones</span></header><article v-for="item in items" :key="item.id"><div><b>#{{String(item.id).padStart(6,'0')}}</b><small>{{item.tipo==='m'?'Material':item.tipo==='a'?'Activo':'Servicio'}} · {{item.es_requerimiento_almacen?'Almacén':'Compra'}}</small></div><p>{{item.informacion}}</p><time>{{item.fecha_registro}}</time><em>{{item.estado_label}}</em><footer><button @click="show(item)">Ver</button><button @click="imprimirPedido(item.id)">Imprimir</button><button v-if="canEdit(item)" @click="open(item)">Editar</button><button v-if="canEdit(item)" class="send" @click="action(item,'enviar')">Enviar</button><button v-if="canEdit(item)" class="cancel" @click="action(item,'anular')">Anular</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page===1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page===lastPage" @click="load(filters.page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><h2>{{editing?'Editar':'Nuevo'}} pedido</h2><button type="button" @click="modal=false">×</button></header><div class="row"><label>Tipo<select v-model="form.tipo"><option value="m">Material</option><option value="a">Activo</option><option value="s">Servicio</option></select></label><label>Prioridad<select v-model="form.prioridad"><option value="normal">Normal</option><option value="urgente">Urgente</option></select></label></div><label>Glosa *<textarea v-model.trim="form.informacion" rows="3"/></label><label class="check"><input v-model="form.es_requerimiento_almacen" type="checkbox"> Requerimiento de almacén</label><h3>Ítems solicitados</h3><div v-for="(line,i) in form.detalles" :key="i" class="line"><select v-model="line.item_id"><option :value="0" disabled>Seleccione un ítem</option><option v-for="item in availableItems" :key="item.id" :value="item.id">{{item.nombre}} {{item.unidad?`(${item.unidad})`:''}}</option></select><input v-model.number="line.cantidad" type="number" min="1"><input v-model.trim="line.glosa" placeholder="Detalle"><button type="button" @click="removeLine(i)">×</button></div><button type="button" class="add" @click="addLine">+ Agregar ítem</button><label>PDF de sustento {{form.es_requerimiento_almacen?'':'*'}}<input type="file" accept="application/pdf" @change="pick"></label><label class="check"><input v-model="form.enviar_copia" type="checkbox"> Enviar copia</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">Guardar pedido</button></footer></form></div><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><h2>Seguimiento #{{detail.id}}</h2><button @click="detail=null">×</button></header><p>{{detail.informacion}}</p><h3>Ítems</h3><div v-for="line in detail.detalles" :key="line.id" class="detail-line"><b>{{line.item}}</b><span>{{line.cantidad}} {{line.unidad}}</span></div><h3>Historial</h3><div v-for="step in detail.seguimiento" :key="step.id" class="detail-line"><b>{{step.estado}}</b><span>{{step.fecha}} · {{step.usuario}}</span><p>{{step.comentario}}</p></div></section></div></div></template>
<style scoped>
