dding:45px;text-align:center;background:#fff;font-size:.64rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.56rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,700px);max-height:90vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:0 0 14px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.58rem}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.check input{width:auto}.modal h3{font-size:.65rem}.line{margin-bottom:6px;display:grid;grid-template-columns:2fr 70px 1fr 28px;gap:5px}.line button{border:0;color:#b44747;background:none}.add{margin-bottom:12px;border:0;color:var(--accent);background:none;font-size:.57rem}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.detail-line{padding:8px;border-bottom:1px solid #e7ebed;font-size:.58rem}.detail-line span{float:right}@media(max-width:900px){.table>header{display:none}.table>article{grid-template-columns:1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}
